import math

def euclidean(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

centroids = {
    "cluster_a": [0.0, 0.0],
    "cluster_b": [10.0, 10.0],
    "cluster_c": [-10.0, 10.0],
    "cluster_d": [10.0, -10.0],
}

clustered_vectors = {
    "cluster_a": [[0.1, 0.1], [0.2, -0.1], [-0.2, 0.3]],
    "cluster_b": [[10.1, 9.8], [9.9, 10.2]],
    "cluster_c": [[-9.8, 10.1], [-10.3, 9.7]],
    "cluster_d": [[10.2, -9.9], [9.8, -10.1]],
}

def ivf_search(query, nprobe):
    ranked_clusters = sorted(centroids, key=lambda c: euclidean(query, centroids[c]))
    probed_clusters = ranked_clusters[:nprobe]   # only the nprobe closest clusters

    best_vec, best_dist, scanned = None, float("inf"), 0
    for cluster_name in probed_clusters:
        for vec in clustered_vectors[cluster_name]:
            scanned += 1
            d = euclidean(query, vec)
            if d < best_dist:
                best_vec, best_dist = vec, d
    return best_vec, scanned

query = [0.0, 0.0]
print(ivf_search(query, nprobe=1))

positions = {"A": 0, "B": 2, "C": 5, "D": 9, "E": 12, "F": 20}

# Layer 1: sparse, long-range "highway" connections -- only 3 of the 6 nodes
layer1_edges = {"A": ["D"], "D": ["A", "F"], "F": ["D"]}

# Layer 0: dense, short-range "local street" connections -- every node
layer0_edges = {
    "A": ["B"], "B": ["A", "C"], "C": ["B", "D"],
    "D": ["C", "E"], "E": ["D", "F"], "F": ["E"],
}

def dist(query, node):
    return abs(query - positions[node])

def greedy_search(query, graph, start):
    current = start
    path = [current]
    while True:
        closer = min(graph[current], key=lambda n: dist(query, n))
        if dist(query, closer) < dist(query, current):
            current = closer
            path.append(current)
        else:
            break   # no neighbor is closer than where we already are
    return current, path

query = 10
landing_node, top_path = greedy_search(query, layer1_edges, start="A")
result, bottom_path = greedy_search(query, layer0_edges, start=landing_node)

print(top_path)
print(bottom_path)
print(result)

