import math

def dist(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

centroids = {"A": (0.0, 0.0), "B": (5.0, 0.0), "C": (0.0, 5.0)}

points = {
    "a1": (0.0, 0.0), "a2": (1.0, 0.0), "a3": (0.0, 1.0), "a4": (1.0, 1.0), "a5": (-1.0, 0.5),
    "b1": (5.0, 0.0), "b2": (4.2, 0.3), "b3": (5.0, 1.0), "b4": (4.6, -0.4),
    "c1": (0.0, 5.0), "c2": (0.3, 4.2), "c3": (1.0, 5.0),
}

assignment = {name: min(centroids, key=lambda c: dist(pt, centroids[c])) for name, pt in points.items()}

query = (3.0, 0.1)
true_top3 = sorted(points, key=lambda name: dist(query, points[name]))[:3]

ranked_clusters = sorted(centroids, key=lambda c: dist(query, centroids[c]))

def ivf_top3(nprobe):
    probed = ranked_clusters[:nprobe]
    candidates = [name for name in points if assignment[name] in probed]
    return sorted(candidates, key=lambda name: dist(query, points[name]))[:3]

def recall_at_3(approx_top3):
    return len(set(approx_top3) & set(true_top3)) / 3

for nprobe in (1, 2, 3):
    approx = ivf_top3(nprobe)
    print(nprobe, approx, recall_at_3(approx))

